import sys; sys.path.insert(0, __file__.rsplit('/', 1)[0])
from abcommon import load, rep, note, save
S = 'india-leads-world-in-jute-and-ranks'
t = load(S)
# jute
t = rep(t, "and the current reservation &mdash; last extended by a Ministry of Textiles order (S.O. 1830(E)) dated 22 April 2025 &mdash; requires <strong>100 per cent of foodgrains and 20 per cent of sugar</strong> moved through government channels to be packed in jute bags,",
        "and the reservation in the most recent order this piece found &mdash; a Ministry of Textiles order (S.O. 1830(E)) dated 22 April 2025, valid only to 30 June 2025, with no later order located &mdash; required <strong>100 per cent of foodgrains and 20 per cent of sugar production</strong> to be packed in jute bags,")
t = rep(t, "The government buys jute bags worth more than <strong>&#8377;7,500 crore a year</strong> under this mandate, on the government's own figures, and the reservation is credited with supporting roughly <strong>7 lakh direct workers and 40 lakh jute farmers</strong>.",
        "The government buys jute bags worth about <strong>&#8377;12,000 crore a year</strong> under this mandate, and the reservation is credited with supporting about <strong>4 lakh workers in jute mills and allied units and 40 lakh farm families</strong>, according to the Cabinet Committee on Economic Affairs&rsquo; decision for 2023-24 (the &#8377;7,500 crore and 7 lakh workers first used here were 2020 figures).")
t = rep(t, "The Jute Packaging Materials Act's 100%-foodgrain/20%-sugar reservation and the 22 April 2025 order (S.O. 1830(E)) extending it are from Drishti IAS, IAS Gyan and worldtradescanner.com's hosting of the order text; the &#8377;7,500-crore annual government purchase figure and the 7-lakh-worker/40-lakh-farmer employment figures are from the same government-press-release sourcing, not independently re-verified against a primary Ministry of Textiles document.",
        "The Jute Packaging Materials Act's 100%-foodgrain/20%-sugar-production reservation and the 22 April 2025 order (S.O. 1830(E)), valid to 30 June 2025, are from Drishti IAS, IAS Gyan and worldtradescanner.com's hosting of the order text; the &#8377;12,000-crore purchase, 4-lakh-worker and 40-lakh-farm-family figures are from the CCEA decision on jute reservation norms for 2023-24 (PIB 1984208).")
# wool
t = rep(t, "and it hosts the third-largest sheep flock on the planet.", "and it has one of the three largest sheep flocks on the planet.")
t = rep(t, "despite India holding the world's third-largest sheep flock</span>", "despite India holding one of the world's three largest sheep flocks</span>")
t = rep(t, "India holds the world's <strong>third-largest sheep population, over 64 million head</strong>, and annual wool production runs in the <strong>43&ndash;46 million kilogram</strong> range &mdash; large numbers on paper.",
        "India holds <strong>74.26 million sheep</strong> (20th Livestock Census, 2019), second or third in the world depending on the source, but annual wool production was only <strong>33.69 million kilograms</strong> in 2023-24 (Basic Animal Husbandry Statistics 2024).")
t = rep(t, "raw wool imports reached <strong>92.2 million kilograms in 2023-24</strong>, surpassing pre-Covid levels, with roughly 18 per cent sourced from Australia",
        "raw wool imports reached <strong>92.2 million kilograms in 2023-24</strong>, surpassing pre-Covid levels, with roughly 18 per cent sourced from Australia (consistent with Australian Wool Innovation&rsquo;s reporting, but not checked against DGCI&amp;S data)")
t = rep(t, "numbers are falling in several of the traditional wool-producing states &mdash; Himachal Pradesh, Rajasthan, Gujarat, Andhra Pradesh and Jammu &amp; Kashmir &mdash;",
        "numbers fell between the 2012 and 2019 livestock censuses in several of the traditional wool-producing states &mdash; Himachal Pradesh, Rajasthan (from 9.1 million to 7.9 million), Gujarat and Jammu &amp; Kashmir &mdash;")
t = rep(t, "India's sheep population (64+ million, third-largest globally), wool production (43-46 million kg/year), raw wool imports (92.2 million kg in 2023-24, ~18% from Australia), the state-wise sheep-population decline (Himachal Pradesh, Rajasthan, Gujarat, Andhra Pradesh, Jammu &amp; Kashmir),",
        "India's sheep population (74.26 million, 20th Livestock Census 2019), wool production (33.69 million kg in 2023-24, BAHS 2024), raw wool imports (92.2 million kg in 2023-24, ~18% from Australia, not checked against DGCI&amp;S), the state-wise sheep-population decline between the 2012 and 2019 censuses (Himachal Pradesh, Rajasthan, Gujarat, Jammu &amp; Kashmir),")
t = note(t, "Several jute and wool figures are corrected. <b>Jute:</b> the 22 April 2025 order cited as the &ldquo;current&rdquo; reservation was valid only to 30 June 2025 and no later order was found; the 20% applies to sugar production; and the &#8377;7,500 crore of purchases and 7 lakh workers were 2020 figures &mdash; the Cabinet&rsquo;s 2023-24 decision gives about &#8377;12,000 crore, 4 lakh workers and 40 lakh farm families. <b>Wool:</b> India had 74.26 million sheep in the 2019 Livestock Census, not &ldquo;over 64 million&rdquo;, and its world rank is second or third depending on the source; wool production was 33.69 million kg in 2023-24, not 43&ndash;46 million kg, so imports of 92.2 million kg (an industry figure not checked against official trade data) are nearly three times domestic output. The state-wise decline compares the 2012 and 2019 censuses, and Andhra Pradesh has been dropped from it because the state was split in between.")
